import { readFile as read } from "node:fs/promises";
"use strict";
function count(n) { return n < 1 ? 0 : count(n - 1); }
export async function load(path) { const raw = await read(path); return String.raw`value=${raw}`; }

#![allow(dead_code)]
use std::future::ready;
macro_rules! identity { ($value:expr) => { $value }; }
fn factorial(n: u64) -> u64 { if n < 2 { 1 } else { n * factorial(n - 1) } }
async fn effect(value: u64) -> u64 { ready(()).await; identity!(value) }
